import { cookies } from 'next/headers'
import { ojsApiUrl, ojsServiceApiKey } from '../ojs/config'

/**
 * Session model.
 *
 * OJS is the identity provider — it owns users, passwords and roles, and the
 * portal must not create a second account store. OJS has no OAuth and its
 * per-user API keys must be generated by hand in the OJS profile, which is not
 * something an author can be asked to do. The remaining option is the one this
 * module implements: portal and OJS share an origin, so the OJS session cookie
 * is presented on requests to /ojs/api/v1 and the portal asks OJS who the
 * caller is.
 *
 * This is undocumented usage of OJS internals and the plan treats it as a
 * go/no-go spike before the dependent features are scoped. See
 * docs/OJS-INTEGRATION.md for the spike checklist and the fallback (link out to
 * OJS for login, portal stays anonymous).
 */

export type SessionUser = {
  id: number
  userName: string
  fullName: string
  givenName?: string
  familyName?: string
  email: string
  orcid?: string
  affiliation?: string
  /** Lowercased OJS role names, e.g. ['author', 'reviewer']. */
  roles: string[]
}

export type Session = { user: SessionUser | null; reason?: string }

/** The OJS 3.x session cookie. Name is configurable in config.inc.php. */
export const OJS_SESSION_COOKIE = process.env.OJS_SESSION_COOKIE || 'OJSSID'

const ROLE_NAMES: Record<number, string> = {
  1: 'site-admin',
  16: 'manager',
  17: 'editor',
  65536: 'author',
  4096: 'reviewer',
  8192: 'assistant',
  1048576: 'reader',
  2097152: 'subscription-manager',
}

type OjsUserPayload = {
  id?: number
  userName?: string
  fullName?: string
  givenName?: Record<string, string> | string
  familyName?: Record<string, string> | string
  email?: string
  orcid?: string
  affiliation?: Record<string, string> | string
  roles?: { roleId?: number }[]
  groups?: { roleId?: number }[]
}

/** OJS returns many fields as { en: "value" } locale maps. */
const localised = (value: Record<string, string> | string | undefined): string | undefined => {
  if (!value) return undefined
  if (typeof value === 'string') return value
  return value.en ?? Object.values(value)[0]
}

export function normaliseOjsUser(payload: OjsUserPayload): SessionUser | null {
  if (!payload.id || !payload.email) return null

  const given = localised(payload.givenName)
  const family = localised(payload.familyName)
  const roleIds = [...(payload.roles ?? []), ...(payload.groups ?? [])]
    .map((r) => r.roleId)
    .filter((id): id is number => typeof id === 'number')

  return {
    id: payload.id,
    userName: payload.userName ?? payload.email,
    fullName: payload.fullName ?? [given, family].filter(Boolean).join(' ') ?? payload.email,
    givenName: given,
    familyName: family,
    email: payload.email,
    orcid: payload.orcid,
    affiliation: localised(payload.affiliation),
    roles: [...new Set(roleIds.map((id) => ROLE_NAMES[id]).filter(Boolean))],
  }
}

/**
 * Resolves the current user by replaying the caller's OJS session cookie to the
 * OJS API. Returns `{ user: null, reason }` rather than throwing: an
 * unauthenticated visitor is the normal case, and a misconfigured or down OJS
 * must degrade to "signed out", never to a 500 on a public page.
 */
export async function getSession(): Promise<Session> {
  const store = await cookies()
  const sid = store.get(OJS_SESSION_COOKIE)?.value

  if (!sid) return { user: null, reason: 'no-session-cookie' }

  try {
    const response = await fetch(ojsApiUrl('index', '/users/me'), {
      headers: {
        Cookie: `${OJS_SESSION_COOKIE}=${sid}`,
        Accept: 'application/json',
        ...(ojsServiceApiKey ? { Authorization: `Bearer ${ojsServiceApiKey}` } : {}),
      },
      // Session state must never be cached across requests.
      cache: 'no-store',
    })

    if (!response.ok) return { user: null, reason: `ojs-${response.status}` }

    const user = normaliseOjsUser((await response.json()) as OjsUserPayload)
    return { user, reason: user ? undefined : 'unparsable-user' }
  } catch (error) {
    return { user: null, reason: error instanceof Error ? error.message : 'ojs-unreachable' }
  }
}

export const hasRole = (session: Session, role: string) => session.user?.roles.includes(role) ?? false
